-- =====================================================================
--  Kestrel Ridge Energy Park — demo database
--  A fictional hybrid plant: 48 MWp solar, 36 MW wind and a
--  20 MW / 80 MWh battery behind one grid connection, supplying an
--  industrial campus and exporting the surplus. Everything is synthetic
--  and generated by 02_seed.sql.
-- =====================================================================

CREATE SCHEMA IF NOT EXISTS plant;
SET search_path TO plant, public;

CREATE TABLE asset (
    asset_id     text PRIMARY KEY,               -- 'PV-01', 'WT-07', 'BESS'
    name         text NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('pv_block', 'wind_turbine', 'bess')),
    capacity_mw  numeric NOT NULL,
    energy_mwh   numeric                         -- BESS only
);

-- Met mast + pyranometer, 15-minute means
CREATE TABLE weather (
    ts        timestamptz PRIMARY KEY DEFERRABLE,   -- deferrable: shift_to_now() moves all rows at once
    ghi_wm2   double precision NOT NULL,         -- global horizontal irradiance
    wind_ms   double precision NOT NULL,         -- hub-height wind speed
    temp_c    double precision NOT NULL
);

-- Active power per asset, 15-minute means.
-- BESS sign convention: + discharging (to site), - charging.
CREATE TABLE asset_power (
    ts        timestamptz NOT NULL,
    asset_id  text NOT NULL REFERENCES asset (asset_id),
    mw        double precision NOT NULL,
    PRIMARY KEY (asset_id, ts) DEFERRABLE
);
CREATE INDEX asset_power_ts_idx ON asset_power (ts);

CREATE TABLE bess_state (
    ts       timestamptz PRIMARY KEY DEFERRABLE,
    soc_pct  double precision NOT NULL
);

-- Point of connection: campus demand and grid exchange (all >= 0)
CREATE TABLE site_meter (
    ts         timestamptz PRIMARY KEY DEFERRABLE,
    load_mw    double precision NOT NULL,
    import_mw  double precision NOT NULL,
    export_mw  double precision NOT NULL
);

-- Day-ahead price and grid carbon intensity, hourly
CREATE TABLE market (
    ts            timestamptz PRIMARY KEY DEFERRABLE,
    price_eur_mwh double precision NOT NULL,
    grid_gco2_kwh double precision NOT NULL
);

-- Unplanned / planned downtime per asset
CREATE TABLE downtime (
    asset_id  text NOT NULL REFERENCES asset (asset_id),
    start_ts  timestamptz NOT NULL,
    end_ts    timestamptz,                       -- NULL = still down
    kind      text NOT NULL CHECK (kind IN ('fault', 'maintenance', 'curtailment')),
    reason    text NOT NULL
);
